   557  // The prize is the value of overlay_offset: the offset of compressed data
   558  tribool PackUnix::canUnpack()
   559  {
   560      int const small = 32 + sizeof(overlay_offset);
   561      // Allow zero-filled last page, for Mac OS X code signing.
   562      int bufsize = 2*4096 + 2*small +1;
   563      if (bufsize > fi->st_size())
   564          bufsize = fi->st_size();
   565      MemBuffer buf(bufsize);
   566
   567      fi->seek(-(off_t)bufsize, SEEK_END);
   568      fi->readx(buf, bufsize);
   569      return find_overlay_offset(buf);
   570  }
