   572  int PackUnix::find_overlay_offset(MemBuffer const &buf)
   573  {
   574      int const small = 32 + sizeof(overlay_offset);
   575      int const bufsize = buf.getSize();
   576      int i = bufsize;
   577      while (i > small && 0 == buf[--i]) { }
   578      i -= small;
   579      // allow incompressible extents
   580      if (i < 0 || !getPackHeader(buf + i, bufsize - i, true))
   581          return false;
   582
   583      int l = ph.buf_offset + ph.getPackHeaderSize();
   584      if (l < 0 || i + l + 4 > bufsize)
   585          throwCantUnpack("file corrupted");
   586      overlay_offset = get_te32(buf + i + l);
   587      if ((off_t)overlay_offset >= file_size)
   588          throwCantUnpack("file corrupted");
   589
   590      return true;
   591  }
