   171  // Returns the size that will be generated based on version and format,
   172  // not necessarily the size that actually is present in spoofed input.
   173  int PackHeader::getPackHeaderSize() const {
   174      if (format < 0 || version < 0)
   175          throwInternalError("getPackHeaderSize");
   176
   177      int n = 0;
   178      if (version <= 3) // Note: covers (version <= 0)
   179          n = 24;
   180      else if (version <= 9) {
   181          if (format == UPX_F_DOS_COM || format == UPX_F_DOS_SYS)
   182              n = 20;
   183          else if (format == UPX_F_DOS_EXE || format == UPX_F_DOS_EXEH)
   184              n = 25;
   185          else
   186              n = 28;
   187      } else {
   188          if (format == UPX_F_DOS_COM || format == UPX_F_DOS_SYS)
   189              n = 22;
   190          else if (format == UPX_F_DOS_EXE || format == UPX_F_DOS_EXEH)
   191              n = 27;
   192          else
   193              n = 32;
   194      }
   195      if (n < 20)
   196          throwCantUnpack("unknown header version");
   197      return n;
   198  }
