   203
   204  void PackHeader::putPackHeader(SPAN_S(byte) p) const {
   205      // NOTE: It is the caller's responsbility to ensure the buffer p has
   206      // sufficient space for the header.
   207      assert(get_le32(p) == UPX_MAGIC_LE32);
   208      if (get_le32(p + 4) != UPX_MAGIC2_LE32) {
   209          NO_fprintf(stderr, "MAGIC2_LE32: %x %x\n", get_le32(p + 4), UPX_MAGIC2_LE32);
   210          throwBadLoader();
   211      }
   212
   213      int size = 0;
   214      int old_chksum = 0;
   215
   216      // the new variable length header
   217      if (format < 128) { // little endian
   218          if (format == UPX_F_DOS_COM || format == UPX_F_DOS_SYS) {
   219              size = 22;
   220              old_chksum = get_packheader_checksum(p, size - 1);
   221              set_le16(p + 16, u_len);
   222              set_le16(p + 18, c_len);
   223              p[20] = (byte) filter;
   224          } else if (format == UPX_F_DOS_EXE) {
   225              size = 27;
   226              old_chksum = get_packheader_checksum(p, size - 1);
   227              set_le24(p + 16, u_len);
   228              set_le24(p + 19, c_len);
   229              set_le24(p + 22, u_file_size);
   230              p[25] = (byte) filter;
   231          } else if (format == UPX_F_DOS_EXEH) {
   232              throwInternalError("invalid format");
   233          } else {
   234              size = 32;
   235              old_chksum = get_packheader_checksum(p, size - 1);
   236              set_le32(p + 16, u_len);
   237              set_le32(p + 20, c_len);
   238              set_le32(p + 24, u_file_size);
   239              p[28] = (byte) filter;
   240              p[29] = (byte) filter_cto;
   241              assert(n_mru == 0 || (n_mru >= 2 && n_mru <= 256));
   242              p[30] = (byte) (n_mru ? n_mru - 1 : 0);
   243          }
   244          set_le32(p + 8, u_adler);
   245          set_le32(p + 12, c_adler);
   246      } else { // big endian
   247          size = 32;
   248          old_chksum = get_packheader_checksum(p, size - 1);
   249          set_be32(p + 8, u_len);
   250          set_be32(p + 12, c_len);
   251          set_be32(p + 16, u_adler);
   252          set_be32(p + 20, c_adler);
   253          set_be32(p + 24, u_file_size);
   254          p[28] = (byte) filter;
   255          p[29] = (byte) filter_cto;
   256          assert(n_mru == 0 || (n_mru >= 2 && n_mru <= 256));
   257          p[30] = (byte) (n_mru ? n_mru - 1 : 0);
   258      }
   259
   260      p[4] = (byte) version;
   261      p[5] = (byte) format;
   262      p[6] = (byte) method;
   263      p[7] = (byte) level;
   264
   265      // header_checksum
   266      assert(size == getPackHeaderSize());
   267      // check old header_checksum
   268      if (p[size - 1] != 0) {
   269          if (p[size - 1] != old_chksum) {
   270              // printf("old_checksum: %d %d\n", p[size - 1], old_chksum);
   271              throwBadLoader();
   272          }
   273      }
   274      // store new header_checksum
   275      p[size - 1] = get_packheader_checksum(p, size - 1);
   276  }
