   376      unsigned new_len = ph.u_len;
   377      int r = upx_test_overlap(buf - src_off, tbuf, src_off, ph.c_len, &new_len, method,
   378                               &ph.compress_result);
   379      if (r == UPX_E_OUT_OF_MEMORY)
   380          throwOutOfMemoryException();
